diff --git a/infra/lib/constructs/orders-data.ts b/infra/lib/constructs/orders-data.ts
new file mode 100644
--- /dev/null
+++ b/infra/lib/constructs/orders-data.ts
@@ -0,0 +1,43 @@
+import { Duration } from "aws-cdk-lib";
+import { Construct } from "constructs";
+import * as dynamodb from "aws-cdk-lib/aws-dynamodb";
+import * as cloudwatch from "aws-cdk-lib/aws-cloudwatch";
+
+export interface OrdersDataProps {
+  stage: "staging" | "production";
+}
+
+/** The orders table, its indexes and the alarms on it. */
+export class OrdersData extends Construct {
+  public readonly table: dynamodb.Table;
+
+  constructor(scope: Construct, id: string, props: OrdersDataProps) {
+    super(scope, id);
+
+    this.table = new dynamodb.Table(this, "OrdersTable", {
+      partitionKey: { name: "pk", type: dynamodb.AttributeType.STRING },
+      sortKey: { name: "sk", type: dynamodb.AttributeType.STRING },
+      billingMode: dynamodb.BillingMode.PAY_PER_REQUEST,
+      pointInTimeRecovery: true,
+      timeToLiveAttribute: "ttl",
+    });
+
+    this.table.addGlobalSecondaryIndex({
+      indexName: "byCustomer",
+      partitionKey: { name: "customerId", type: dynamodb.AttributeType.STRING },
+      sortKey: { name: "createdAt", type: dynamodb.AttributeType.STRING },
+    });
+
+    if (props.stage === "production") {
+      new cloudwatch.Alarm(this, "ThrottleAlarm", {
+        metric: this.table.metric("WriteThrottleEvents", {
+          period: Duration.minutes(1),
+          statistic: "Sum",
+        }),
+        threshold: 10,
+        evaluationPeriods: 3,
+        treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,
+      });
+    }
+  }
+}
