+import type { SQSEvent } from "aws-lambda";
+import { psp } from "./psp";
+
+// Captures an authorised card payment at the PSP for each message.
+export async function handler(event: SQSEvent): Promise<void> {
+  for (const record of event.Records) {
+    const { authorisationId, amountMinor, currency } = JSON.parse(record.body);
+    await psp.capture({ authorisationId, amountMinor, currency });
+  }
+}

